from typing import Optional
from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

app = FastAPI()
RUNS = {1: {"id": 1, "test": "test_attach", "status": "fail"}}

class RunIn(BaseModel):
    test: str
    status: str

@app.get("/api/v1/runs/{run_id}")          # path param: which resource
def get_run(run_id: int):
    if run_id not in RUNS:
        raise HTTPException(status_code=404, detail="run not found")
    return RUNS[run_id]                     # dict -> JSON response

@app.get("/api/v1/runs")                    # query params: filter/paginate
def list_runs(status: Optional[str] = None, limit: int = Query(50, le=200)):
    rows = [r for r in RUNS.values() if status is None or r["status"] == status]
    return {"items": rows[:limit]}

@app.post("/api/v1/runs", status_code=201)  # JSON body validated by Pydantic
def create_run(body: RunIn):
    rid = max(RUNS) + 1
    RUNS[rid] = {"id": rid, **body.model_dump()}
    return RUNS[rid]

@app.get("/", response_class=HTMLResponse)
def index():
    return "<h1>CI dashboard</h1><script>fetch('/api/v1/runs')" \
           ".then(r => r.json()).then(d => document.body.append(JSON.stringify(d)))</script>"
```
- **Path vs query:** path identifies a resource (`/runs/42`); query modifies a collection request (`?status=fail&limit=10`).
- Type hints drive validation: `/runs/abc`, `?limit=999`, or a body missing `status` all return **422** automatically. Run with `uvicorn app:app --reload`; interactive docs at `/docs`.

